import * as THREE from 'three';
import {dimensions,normalizeModel} from './model-ops.js';
import {zipSync,strToU8} from './vendor/fflate.js';
const TILE=64,COLS=32,SIZE=2048;
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const n=x=>Math.abs(x)<1e-9?'0':Number(x.toFixed(8)).toString();
const matrix=p=>new THREE.Matrix4().compose(new THREE.Vector3(...p.p),new THREE.Quaternion(...p.q),new THREE.Vector3(1,1,1));
const translation=a=>new THREE.Matrix4().makeTranslation(...a);
const cf=(name,m=new THREE.Matrix4())=>{const e=m.elements;return `<CoordinateFrame name="${name}"><X>${n(e[12])}</X><Y>${n(e[13])}</Y><Z>${n(e[14])}</Z>${[0,1,2].map(r=>[0,1,2].map(c=>`<R${r}${c}>${n(e[c*4+r])}</R${r}${c}>`).join('')).join('')}</CoordinateFrame>`;};
const prop=(tag,name,v)=>`<${tag} name="${name}">${v}</${tag}>`;
const item=(type,ref,properties,children='')=>`<Item class="${type}" referent="${ref}"><Properties>${properties}</Properties>${children}</Item>`;
const name=s=>prop('string','Name',escape(s));
function motor(id,parent,a,b){return item('Motor6D',`M${id}`,name(`Joint_${id}`)+prop('Ref','Part0',parent)+prop('Ref','Part1',`P${id}`)+cf('C0',translation(a))+cf('C1',translation(b)));}
export function robloxXML(state){const root=state.boxes.find(b=>b.parent===null),rootCF=matrix(root);let parts='';
parts+=item('Part','RIGROOT',name('RigRoot')+cf('CFrame',rootCF)+prop('Vector3','size','<X>0.1</X><Y>0.1</Y><Z>0.1</Z>')+prop('bool','Anchored','true')+prop('bool','CanCollide','false')+prop('bool','CanQuery','false')+prop('bool','CanTouch','false')+prop('float','Transparency','1'),motor(root.id,'RIGROOT',[0,0,0],[0,0,0]));
for(const b of state.boxes){const color=new THREE.Color(b.color);const rgb=(255<<24)|((Math.round(color.getHex()>>16&255))<<16)|(color.getHex()&65535);let joints='';for(const child of state.boxes.filter(c=>c.parent===b.id))joints+=motor(child.id,`P${b.id}`,child.a,child.b);
const meta=item('BoolValue',`ANCHOR${b.id}`,name('EditorAnchor')+prop('bool','Value',String(b.anchor)))+item('IntValue',`SLOT${b.id}`,name('AtlasSlot')+prop('int','Value',b.slot))+item('StringValue',`AXIS${b.id}`,name('EditorJointAxis')+prop('string','Value',b.axis||'omni'));
parts+=item('Part',`P${b.id}`,name(`Cube_${b.id}`)+cf('CFrame',matrix(b))+prop('Vector3','size',dimensions(b).map((v,i)=>`<${'XYZ'[i]}>${n(v)}</${'XYZ'[i]}>`).join(''))+prop('bool','Anchored','false')+prop('bool','CanCollide','false')+prop('bool','Massless','true')+prop('token','shape','1')+prop('token','TopSurface','0')+prop('token','BottomSurface','0')+prop('Color3uint8','Color3uint8',rgb>>>0),joints+meta);}
const frames=state.frames.length?state.frames:[{time:0,pose:Object.fromEntries(state.boxes.map(b=>[b.id,b]))}];
function pose(b,frame,i){const p=frame.pose[b.id]||b;let transform;if(b.parent===null){transform=rootCF.clone().invert().multiply(matrix(p));}else{const parent=frame.pose[b.parent]||state.boxes.find(c=>c.id===b.parent);transform=translation(b.a).invert().multiply(matrix(parent).invert()).multiply(matrix(p)).multiply(translation(b.b));}return item('Pose',`F${i}P${b.id}`,name(`Cube_${b.id}`)+cf('CFrame',transform)+prop('float','Weight','1')+prop('token','EasingStyle','0')+prop('token','EasingDirection','0'),state.boxes.filter(c=>c.parent===b.id).map(c=>pose(c,frame,i)).join(''));}
const keyframes=frames.map((f,i)=>item('Keyframe',`KEY${i}`,name(`Keyframe_${i}`)+prop('float','Time',n(f.time)),item('Pose',`F${i}ROOT`,name('RigRoot')+cf('CFrame')+prop('float','Weight','1'),pose(root,f,i)))).join('');
const sequence=item('KeyframeSequence','SEQUENCE',name('CubeAnimation')+prop('bool','Loop','true')+prop('token','Priority','2'),keyframes);
const controller=item('AnimationController','CONTROLLER',name('AnimationController'),item('Animator','ANIMATOR',name('Animator')));
return `<?xml version="1.0" encoding="utf-8"?><roblox xmlns:xmime="http://www.w3.org/2005/05/xmlmime" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" version="4"><External>null</External><External>nil</External>${item('Model','MODEL',name('CubeModel')+prop('Ref','PrimaryPart','RIGROOT'),parts+sequence+controller)}</roblox>`;}
export function meshOBJ(box,geometry){const pos=geometry.attributes.position,uv=geometry.attributes.uv,norm=geometry.attributes.normal,index=geometry.index;let text=`mtllib atlas.mtl\no Cube_${box.id}\nusemtl Atlas\n`;for(let i=0;i<pos.count;i++)text+=`v ${n(pos.getX(i)*dimensions(box)[0])} ${n(pos.getY(i)*dimensions(box)[1])} ${n(pos.getZ(i)*dimensions(box)[2])}\n`;for(let i=0;i<uv.count;i++)text+=`vt ${n(uv.getX(i))} ${n(uv.getY(i))}\n`;for(let i=0;i<norm.count;i++)text+=`vn ${n(norm.getX(i))} ${n(norm.getY(i))} ${n(norm.getZ(i))}\n`;for(let i=0;i<index.count;i+=3){text+='f '+[0,1,2].map(j=>{const v=index.getX(i+j)+1;return `${v}/${v}/${v}`;}).join(' ')+'\n';}return text;}
export function triggerDownload(data,filename,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
export function projectData(state,atlas){return {format:'cube-studio',version:2,state:structuredClone(state),atlas:atlas.toDataURL('image/png')};}
export function downloadProject(state,atlas){triggerDownload(JSON.stringify(projectData(state,atlas)),'model.cube','application/json');}
export async function downloadBundle(state,atlas,meshes){const png=await new Promise((resolve,reject)=>atlas.toBlob(b=>b?b.arrayBuffer().then(resolve):reject(Error('Texture export failed')),'image/png'));
const files={'model.rbxmx':strToU8(robloxXML(state)),'model.cube':strToU8(JSON.stringify(projectData(state,atlas))),'meshes/atlas.png':new Uint8Array(png),'meshes/atlas.mtl':strToU8('newmtl Atlas\nKa 1 1 1\nKd 1 1 1\nKs 0 0 0\nd 1\nillum 1\nmap_Kd atlas.png\n')};
for(const b of state.boxes)files[`meshes/Cube_${b.id}.obj`]=strToU8(meshOBJ(b,meshes.get(b.id).geometry));
files['README.txt']=strToU8(`CUBE STUDIO EXPORT\n\nmodel.rbxmx: Import with Insert from File in Roblox Studio. Contains Parts, Motor6D joints, an AnimationController/Animator, and a nested KeyframeSequence named CubeAnimation. The transparent anchored RigRoot is the animation root. The authoring anchor pins are preserved in EditorAnchor values; the cube Parts themselves stay unanchored so Motor6D animation can move them.\n\nPAINT\nPaint is stored in one 2048 x 2048 atlas: meshes/atlas.png. All companion OBJ meshes use this same texture with unique face UVs. The .rbxmx uses plain Parts until these meshes and the texture are uploaded to Roblox. Roblox model XML cannot embed local mesh or image assets as published asset IDs. No assets have been uploaded.\n\nUpload each meshes/Cube_ID.obj through the Studio 3D Importer and upload atlas.png once. Replace the corresponding Part with its imported MeshPart, preserving its name, CFrame, size, children, and Motor6D Part0/Part1 references. Set every MeshPart TextureID to the same uploaded atlas asset ID. The OBJ geometry is centered at its local origin and includes its authored size. Each Part preserves that size. EditorJointAxis preserves the joint's authoring axis; Motor6D animation contains the resulting constrained poses.\n\nANIMATION\nOpen or import CubeAnimation into the Studio Animation Editor for the rig and publish it when ready. Runtime playback requires a published animation asset ID; a KeyframeSequence alone does not auto-play. Preview easing is linear between joint rotations and the final keyframe loops back to the first.\n\nPROJECT\nmodel.cube preserves every cube, anchor, brush stroke, and keyframe. Open it in Cube Studio using Build > folder > Open project. Units are Roblox studs. No gravity is used in authoring.\n\nThis export has not yet been tested inside Roblox Studio or a live Roblox game.\n`);
triggerDownload(zipSync(files,{level:6}),'cube-model.zip','application/zip');}
export async function readProject(file){if(file.size>30*1024*1024)throw Error('Project is too large');const data=JSON.parse(await file.text()),s=data.state;const fail=()=>{throw Error('Invalid Cube Studio project');};if(data.format!=='cube-studio'||![1,2].includes(data.version)||!s||!Array.isArray(s.boxes)||s.boxes.length<1||s.boxes.length>128||!Array.isArray(s.frames)||s.frames.length>60)fail();
const validArray=(a,length)=>Array.isArray(a)&&a.length===length&&a.every(n=>typeof n==='number'&&Number.isFinite(n)&&Math.abs(n)<10000);const validQ=q=>validArray(q,4)&&Math.abs(Math.hypot(...q)-1)<.01;const ids=new Set(),slots=new Set();for(let i=0;i<s.boxes.length;i++){const b=s.boxes[i];if(!Number.isInteger(b.id)||b.id<0||ids.has(b.id)||!Number.isInteger(b.slot)||b.slot<0||b.slot>=128||slots.has(b.slot)||!validArray(b.p,3)||!validQ(b.q)||typeof b.anchor!=='boolean'||!/^#[0-9a-f]{6}$/i.test(b.color))fail();if(i===0){if(b.id!==0||b.parent!==null)fail();}else if(!ids.has(b.parent)||!validArray(b.a,3)||!validArray(b.b,3))fail();ids.add(b.id);slots.add(b.slot);if(b.size!==undefined&&(!validArray(b.size,3)||b.size.some(v=>v<.2||v>12)))fail();if(b.axis!==undefined&&!['omni','x','y','z'].includes(b.axis))fail();if(b.normal!==undefined&&(!validArray(b.normal,3)||b.normal.filter(v=>Math.abs(v)===1).length!==1||b.normal.filter(v=>v===0).length!==2))fail();}
if(!Number.isInteger(s.nextId)||s.nextId<=Math.max(...ids)||!Number.isInteger(s.frame)||s.frame<0||s.frame>=Math.max(1,s.frames.length))fail();let prev=-1;for(const f of s.frames){if(typeof f.time!=='number'||!Number.isFinite(f.time)||f.time<0||f.time>60||f.time<=prev||!f.pose)fail();for(const b of s.boxes)if(!f.pose[b.id]||!validArray(f.pose[b.id].p,3)||!validQ(f.pose[b.id].q))fail();prev=f.time;}if(s.frames.length&&s.frames[0].time!==0)fail();if(typeof data.atlas!=='string'||!data.atlas.startsWith('data:image/png;base64,')||data.atlas.length>24*1024*1024)fail();const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Invalid paint texture'));image.src=data.atlas;});if(image.width!==SIZE||image.height!==SIZE)fail();return {state:normalizeModel(s),image};}
